    faqs: [
      { q: "What is tempeh, exactly?", a: "Fermented soybeans pressed into a firm cake \u2014 nutty, hearty, and with 20g of protein per 100g, one of the most protein-dense plant foods. The fermentation also makes it easier to digest than plain tofu for many people." },
      { q: "I have only had bland tempeh \u2014 help?", a: "Bland tempeh is under-seasoned tempeh. It is a sponge: the soy-maple marinade plus a hard sear gives it the caramelized crust that makes it craveable. Steam it 10 minutes first if you find it bitter." },
      { q: "Can I use tofu instead?", a: "Yes \u2014 extra-firm tofu, pressed well, seared the same way. You lose a little protein and gain calcium (if calcium-set)." },
      { q: "Is tempeh gluten-free?", a: "Pure tempeh is, but some brands add grains. Check the label if it matters, and use tamari instead of soy sauce." },
      { q: "Can I meal-prep this?", a: "One of the best bowls for it. Keep the dressing separate and everything holds 4 days. The flavors actually meld nicely by day two." },
      { q: "Why massage the cabbage?", a: "Thirty seconds of squeezing breaks down tough cell walls \u2014 it goes from harsh and squeaky to silky and sweet. Try it once and you will never skip it." },
      { q: "Nut-free dressing option?", a: "The tahini IS the nut-free option (it is sesame). If sesame is also an issue, blend sunflower-seed butter the same way." },
      { q: "Where do I buy tempeh?", a: "Refrigerated section near the tofu in most supermarkets, or any Asian grocery. It keeps weeks unopened." },
    ],
